// Extract and validate incoming data from webhook
// Webhook data comes in $input.first().json.body for POST requests
const rawInput = $input.first().json;

// The data could be directly in json (if testing) or in json.body (from actual webhook)
const data = rawInput.body || rawInput;

// Debug: log what we received
console.log('Raw input keys:', Object.keys(rawInput));
console.log('Data keys:', Object.keys(data));
console.log('run_id:', data.run_id);
console.log('webhooks:', data.webhooks);

// Validate required fields
if (!data.run_id) {
  throw new Error('Missing run_id in webhook payload');
}
if (!data.webhooks) {
  throw new Error('Missing webhooks object in payload. Keys received: ' + Object.keys(data).join(', '));
}

return [{ json: data }];

